-- Fixups after the Qur'an word bank load (applied once, 2026-10-30).
-- Excerpts are copied from the verse text by script; each update only touches rows this load created.
update public.words set quran_example='كُلُّ مَنْ عَلَيْهَا فَانٍ', quran_example_en='Everyone on it will perish', quran_reference='Ar-Rahman 55:26' where key='فاني' and created_by is null and quran_example is null;
update public.words set quran_example='فَلَمَّا أَفَاقَ قَالَ سُبْحَانَكَ', quran_example_en='And when he came to, he said: Glory be to You', quran_reference='Al-A''raf 7:143' where key='افاق' and created_by is null and quran_example is null;
update public.words set quran_example='صَيْحَةً وَاحِدَةً مَا لَهَا مِنْ فَوَاقٍ', quran_example_en='a single blast, with no pause in it', quran_reference='Sad 38:15' where key='فواق' and created_by is null and quran_example is null;
update public.words set quran_example='بَقْلِهَا وَقِثَّائِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا', quran_example_en='its herbs, its cucumbers, its garlic, its lentils and its onions', quran_reference='Al-Baqarah 2:61' where key='فوم' and created_by is null and quran_example is null;
update public.words set quran_example='كَمْ مِنْ فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً', quran_example_en='How many a small group has overcome a large group', quran_reference='Al-Baqarah 2:249' where key='فئه' and created_by is null and quran_example is null;
insert into public.words (key,word,word_voweled,english,root,word_type,gender,fusha_plural,companion_forms,quran_example,quran_example_en,quran_reference) select 'فم','فَم','فَم','mouth','ف-و-ه','noun','m','أَفْواه','[{"form": "أَفْواه", "label": "Plural (mouths)"}, {"form": "فُوَّهة", "label": "Noun (muzzle, mouth, crater)"}, {"form": "تَفَوَّهَ", "label": "Form V verb (to utter, to speak out)"}]'::jsonb,'يَقُولُونَ بِأَفْوَاهِهِمْ مَا لَيْسَ فِي قُلُوبِهِمْ','They say with their mouths what is not in their hearts','Al Imran 3:167' where not exists (select 1 from public.words where key='فم');
update public.words set companion_forms = coalesce(companion_forms,'[]'::jsonb) || '[{"form":"فَم","label":"Noun (mouth)"}]'::jsonb where key in ('افواه','فوهه','تفوه') and created_by is null and not (coalesce(companion_forms,'[]'::jsonb) @> '[{"form":"فَم"}]'::jsonb);
update public.words set english='Il-Yasin (a form of Elijah''s name, 37:130)' where key='ياسين' and created_by is null;
update public.words set english='Arim (the dam or flood of Saba)' where key='عرم' and created_by is null;